/* ImageFile>>writeSnapshot: */
bool write_snapshot(char *path)
{
    image_header local;
    image_header *h;
    FILE *f;
    bool ok;
    if (c4_enabled) {
        return false;
    }
    full_gc();
    memset(&local, 0, sizeof local);
    h = &local;
    h->version = 1;
    h->header_size = 64;
    memcpy(h->magic, "SAMALTK1", 8);
    h->heap_bytes = old_top - old_lo;
    h->base = old_lo;
    h->specials = specials_oop;
    h->hash_seed = hash_box[0];
    h->string_hash = word_hash ? 1 : 0;
    f = fopen(path, "wb");
    if (f == NULL) {
        return false;
    }
    ok = (fwrite(h, sizeof(image_header), 1, f) == 1) && (fwrite((void *)old_lo, 1, h->heap_bytes, f) == h->heap_bytes);
    return (fclose(f) == 0) && ok;
}

